SELECT * FROM train_job
WHERE execution_mode='SSH' AND status='QUEUED' AND updated_at <= #{cutoff}
ORDER BY updated_at, job_id LIMIT #{limit}

SELECT * FROM train_job
WHERE execution_mode='SSH' AND status='ALLOCATED'
ORDER BY updated_at, job_id LIMIT #{limit}

SELECT * FROM train_job
WHERE execution_mode='SSH' AND status IN ('STARTING','RUNNING','STOPPING','RECONCILING','UNKNOWN','QUARANTINED')
ORDER BY updated_at, job_id LIMIT #{limit}

SELECT * FROM train_job


        owner_user_id = #{ownerUserId}


        AND job_id < #{beforeJobId}


ORDER BY job_id DESC
LIMIT #{limit}

SELECT COUNT(*) FROM train_job
WHERE status IN ('PENDING','QUEUED','ALLOCATING','ALLOCATED','STARTING','RUNNING','STOPPING','RECONCILING','UNKNOWN','QUARANTINED')
AND owner_user_id = #{ownerUserId}

mapper.update:
UPDATE train_job
SET status = #{newStatus}, updated_at = #{updatedAt}
WHERE job_id = #{jobId} AND status = #{expectedStatus}

UPDATE train_job
SET runner_id = #{runnerId}, start_command_id = #{startCommandId},
    process_spec_json = CAST(#{processSpecJson} AS JSON),
    status = 'STARTING', updated_at = #{updatedAt}
WHERE job_id = #{jobId}

UPDATE train_job
SET stop_command_id = #{stopCommandId}, updated_at = #{updatedAt}
WHERE job_id = #{jobId}
